package main

import (
	"fmt"
	"os"

	tea "github.com/charmbracelet/bubbletea"
	"github.com/Nomadcxx/sysc-Go/ui/floydui"
)

func main() {
	// Create the FLOYD UI model
	model := floydui.NewModel()

	p := tea.NewProgram(
		model,
		tea.WithAltScreen(),
		tea.WithMouseCellMotion(),
		tea.WithFPS(30), // For animations
	)

	if _, err := p.Run(); err != nil {
		fmt.Printf("Error: %v", err)
		os.Exit(1)
	}
}

package floydui

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"

	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/bubbles/progress"
	"github.com/charmbracelet/bubbles/textinput"
	"github.com/charmbracelet/bubbles/viewport"
	"github.com/charmbracelet/lipgloss"

	"github.com/Nomadcxx/sysc-Go/agent"
	"github.com/Nomadcxx/sysc-Go/agent/floyd"
	"github.com/Nomadcxx/sysc-Go/agent/loop"
	agenttools "github.com/Nomadcxx/sysc-Go/agent/tools"
	"github.com/Nomadcxx/sysc-Go/cache"
)

// Session data for persistence
type Session struct {
	Messages []string `json:"messages"`
	History  []string `json:"history"`
}

// ChatMessage represents a message in the chat
type ChatMessage struct {
	Role        string
	Content     string
	ToolUse     *ToolUseInfo
	ToolResult  *ToolResultInfo
	IsStreaming bool
}

// ToolUseInfo contains information about a tool use
type ToolUseInfo struct {
	Name string
	ID   string
}

// ToolResultInfo contains information about a tool result
type ToolResultInfo struct {
	Name    string
	Content string
	IsError bool
}

// Model is the shared FLOYD UI model
type Model struct {
	// UI Components
	Viewport     viewport.Model
	Input        textinput.Model
	Progress     progress.Model

	// State
	Messages     []ChatMessage
	History      []string
	HistoryIndex int
	Ready        bool
	Width        int
	Height       int

	// Theme
	CurrentTheme Theme

	// Thinking state
	IsThinking      bool
	CurrentThinking int
	AnimationFrame int
	LastTick        time.Time

	// Error state
	HasError  bool
	LastError string

	// Help
	ShowHelp bool

	// Progress
	ProgressActive  bool
	ProgressPercent float64

	// Session
	SessionPath string

	// FLOYD Brain (shared across all interfaces)
	ProxyClient  *agent.ProxyClient
	LoopAgent    *loop.LoopAgent
	ToolExecutor *agenttools.Executor
	ProtocolMgr  *floyd.ProtocolManager
	Safety       *floyd.SafetyEnforcer
	CacheMgr     *cache.CacheManager

	// Conversation state
	Conversation []agent.Message

	// Streaming state
	CurrentResponse   strings.Builder
	PendingTokens     []string
	TokenStreamChan   chan string
	StreamCancel      context.CancelFunc
	StreamWaitGroup   sync.WaitGroup

	// Tool execution state
	ExecutingTools  bool
	CurrentToolName string
	ToolIteration   int
}

// NewModel creates a new FLOYD UI model
func NewModel() Model {
	// Initialize styles
	InitStyles()

	// Session path
	sessionPath, _ := os.UserHomeDir()
	sessionPath = filepath.Join(sessionPath, ".floyd_session.json")

	// Load session
	session, _ := loadSession(sessionPath)

	// Convert loaded messages to ChatMessage format
	messages := make([]ChatMessage, 0, len(session.Messages))
	for _, msg := range session.Messages {
		if strings.HasPrefix(msg, "USER:") {
			messages = append(messages, ChatMessage{
				Role:    "user",
				Content: strings.TrimPrefix(msg, "USER: "),
			})
		} else if strings.HasPrefix(msg, "FLOYD:") {
			messages = append(messages, ChatMessage{
				Role:    "assistant",
				Content: strings.TrimPrefix(msg, "FLOYD: "),
			})
		}
	}

	ti := textinput.New()
	ti.Placeholder = "Ask FLOYD..."
	ti.Focus()
	ti.CharLimit = 500
	ti.Width = 60
	ti.Prompt = "> "

	vp := viewport.New(0, 0)

	prog := progress.New(
		progress.WithDefaultGradient(),
		progress.WithWidth(40),
		progress.WithoutPercentage(),
	)

	// Load config and initialize FLOYD brain
	cfg := loadConfig()

	// Validate API key
	if cfg.apiKey == "" {
		messages = append(messages, ChatMessage{
			Role:    "system",
			Content: "ERROR: No API key configured. Set ANTHROPIC_AUTH_TOKEN or GLM_API_KEY environment variable.",
		})
		return Model{
			Viewport:     vp,
			Input:        ti,
			Progress:     prog,
			Messages:     messages,
			History:      session.History,
			HistoryIndex: len(session.History),
			Ready:        true,
			SessionPath:  sessionPath,
			HasError:     true,
			LastError:    "No API key configured",
		}
	}

	proxyClient := agent.NewProxyClient(cfg.apiKey, cfg.baseURL)
	if cfg.model != "" {
		proxyClient.SetModel(cfg.model)
	}

	toolExecutor := agenttools.NewExecutor(30 * time.Second)
	protocolMgr := floyd.NewProtocolManager(".floyd")
	safety := floyd.NewSafetyEnforcer()
	loopAgent := loop.NewLoopAgent(proxyClient, toolExecutor)

	// Add welcome message if no messages
	if len(messages) == 0 {
		messages = append(messages, ChatMessage{
			Role:    "system",
			Content: "FLOYD: PRISM side initialized. Full protocol loaded. Tools armed. Safety enabled.",
		})
	}

	return Model{
		Viewport:         vp,
		Input:            ti,
		Progress:         prog,
		Messages:         messages,
		History:          session.History,
		HistoryIndex:     len(session.History),
		Ready:            false,
		CurrentTheme:     DefaultTheme,
		IsThinking:       false,
		CurrentThinking:  0,
		AnimationFrame:   0,
		LastTick:         time.Now(),
		HasError:         false,
		ShowHelp:         false,
		ProgressActive:   false,
		ProgressPercent:  0.0,
		SessionPath:      sessionPath,
		ProxyClient:      proxyClient,
		LoopAgent:        loopAgent,
		ToolExecutor:     toolExecutor,
		ProtocolMgr:      protocolMgr,
		Safety:           safety,
		CacheMgr:         cache.NewCacheManager(".floyd/.cache"),
		Conversation:     make([]agent.Message, 0),
		PendingTokens:    make([]string, 0, 50),
		TokenStreamChan:  make(chan string, 100),
	}
}

// Init initializes the model
func (m Model) Init() tea.Cmd {
	return tea.Batch(
		textinput.Blink,
		Tick(time.Millisecond*150),
	)
}

// config holds configuration
type config struct {
	apiKey  string
	baseURL string
	model   string
}

// loadConfig loads configuration from environment
func loadConfig() config {
	apiKey := os.Getenv("ANTHROPIC_AUTH_TOKEN")
	if apiKey == "" {
		apiKey = os.Getenv("GLM_API_KEY")
	}
	if apiKey == "" {
		apiKey = os.Getenv("ZHIPU_API_KEY")
	}
	if apiKey == "" {
		homeDir, _ := os.UserHomeDir()
		data, _ := os.ReadFile(homeDir + "/.claude/settings.json")
		var settings struct {
			Env struct {
				AnthropicAuthToken string `json:"ANTHROPIC_AUTH_TOKEN"`
			} `json:"env"`
		}
		if json.Unmarshal(data, &settings) == nil {
			apiKey = settings.Env.AnthropicAuthToken
		}
	}

	return config{
		apiKey:  apiKey,
		baseURL: "https://api.z.ai/api/anthropic",
		model:   "claude-opus-4",
	}
}

var sessionMutex sync.Mutex

// loadSession loads session from disk with corrupt file recovery
func loadSession(path string) (Session, error) {
	sessionMutex.Lock()
	defer sessionMutex.Unlock()

	var s Session
	file, err := os.ReadFile(path)
	if err != nil {
		return s, err
	}

	err = json.Unmarshal(file, &s)
	if err != nil {
		// Move corrupt file for recovery
		corruptPath := path + ".corrupt"
		_ = os.Rename(path, corruptPath)
		return s, fmt.Errorf("session file corrupt, moved to %s: %w", corruptPath, err)
	}
	return s, nil
}

// saveSession saves session to disk atomically
func saveSession(s Session, path string) error {
	sessionMutex.Lock()
	defer sessionMutex.Unlock()

	data, err := json.MarshalIndent(s, "", "  ")
	if err != nil {
		return err
	}

	// Atomic write: temp file + rename
	tmpPath := path + ".tmp"
	if err := os.WriteFile(tmpPath, data, 0644); err != nil {
		return err
	}
	return os.Rename(tmpPath, path)
}

// SaveCurrentSession saves the current model state
func (m Model) SaveCurrentSession() error {
	// Convert ChatMessages to strings for storage
	messages := make([]string, 0, len(m.Messages))
	for _, msg := range m.Messages {
		switch msg.Role {
		case "user":
			messages = append(messages, "USER: "+msg.Content)
		case "assistant":
			messages = append(messages, "FLOYD: "+msg.Content)
		case "system":
			if msg.ToolUse != nil {
				messages = append(messages, "SYSTEM: [Tool: "+msg.ToolUse.Name+"]")
			} else if msg.ToolResult != nil {
				messages = append(messages, "SYSTEM: [Tool Result: "+msg.ToolResult.Name+"]")
			} else {
				messages = append(messages, "SYSTEM: "+msg.Content)
			}
		}
	}

	s := Session{
		Messages: messages,
		History:  m.History,
	}
	return saveSession(s, m.SessionPath)
}

// SetTheme changes the current theme
func (m *Model) SetTheme(name string) tea.Cmd {
	if newTheme, ok := Themes[name]; ok {
		m.CurrentTheme = newTheme
		SetTheme(newTheme)
		m.Input.PromptStyle = lipgloss.NewStyle().Foreground(m.CurrentTheme.Pink)
		return func() tea.Msg {
			return themeChangedMsg{themeName: name}
		}
	}
	return nil
}

// AddUserMessage adds a user message to the conversation
func (m *Model) AddUserMessage(content string) {
	m.Messages = append(m.Messages, ChatMessage{
		Role:    "user",
		Content: content,
	})
	m.Conversation = append(m.Conversation, agent.Message{
		Role:    "user",
		Content: content,
	})
	m.History = append(m.History, content)
	m.HistoryIndex = len(m.History)
}

// AddAssistantMessage adds an assistant message to the conversation
func (m *Model) AddAssistantMessage(content string) {
	m.Messages = append(m.Messages, ChatMessage{
		Role:    "assistant",
		Content: content,
	})
	m.Conversation = append(m.Conversation, agent.Message{
		Role:    "assistant",
		Content: content,
	})
}

// AddSystemMessage adds a system message
func (m *Model) AddSystemMessage(content string) {
	m.Messages = append(m.Messages, ChatMessage{
		Role:    "system",
		Content: content,
	})
}

// AddToolUse adds a tool use notification
func (m *Model) AddToolUse(toolName, toolID string) {
	m.Messages = append(m.Messages, ChatMessage{
		Role:    "system",
		ToolUse: &ToolUseInfo{Name: toolName, ID: toolID},
	})
}

// AddToolResult adds a tool result message
func (m *Model) AddToolResult(toolName, content string, isError bool) {
	m.Messages = append(m.Messages, ChatMessage{
		Role:       "system",
		ToolResult: &ToolResultInfo{Name: toolName, Content: content, IsError: isError},
	})
}

// ClearMessages clears all messages
func (m *Model) ClearMessages() {
	m.Messages = make([]ChatMessage, 0)
	m.Conversation = make([]agent.Message, 0)
}

// GetLastUserMessage returns the last user message
func (m *Model) GetLastUserMessage() string {
	for i := len(m.Messages) - 1; i >= 0; i-- {
		if m.Messages[i].Role == "user" {
			return m.Messages[i].Content
		}
	}
	return ""
}

package floydui

import (
	"fmt"
	"strings"

	"github.com/charmbracelet/lipgloss"
)

// View renders the UI
func (m Model) View() string {
	if !m.Ready {
		return "\n  Initializing FLOYD..."
	}

	// Header with PRISM banner
	header := Styles.Header.Render(PRISMBanner)

	// Tagline
	tagline := Styles.Tagline.Render(GetRandomTagline())

	// Error panel (if any)
	var errorPanel string
	if m.HasError {
		errorPanel = Styles.Error.Render(m.LastError)
	}

	// Help panel (if shown)
	var helpPanel string
	if m.ShowHelp {
		helpPanel = Styles.Help.Render(HelpContent)
	}

	// Build chat history
	var chatHistory strings.Builder
	for i, msg := range m.Messages {
		var styled string
		switch msg.Role {
		case "user":
			styled = Styles.UserMsg.
				Width(m.Width-4).
				Render("YOU: " + msg.Content)
		case "assistant":
			styled = Styles.FloydMsg.Render("FLOYD: " + msg.Content)
		case "system":
			if msg.ToolUse != nil {
				styled = Styles.ToolUse.Render("▶ Using tool: " + msg.ToolUse.Name)
			} else if msg.ToolResult != nil {
				prefix := "✓ "
				if msg.ToolResult.IsError {
					prefix = "✗ "
				}
				content := msg.ToolResult.Content
				if len(content) > 200 {
					content = content[:200] + "..."
				}
				if msg.ToolResult.IsError {
					styled = Styles.ToolResultError.Render(prefix + msg.ToolResult.Name + ": " + content)
				} else {
					styled = Styles.ToolResult.Render(prefix + msg.ToolResult.Name + ": " + content)
				}
			} else {
				styled = Styles.SystemMsg.Render(msg.Content)
			}
		}
		chatHistory.WriteString(styled + "\n")

		// Show thinking animation for last message if thinking
		if m.IsThinking && i == len(m.Messages)-1 && msg.Role == "system" {
			state := ThinkingStates[m.CurrentThinking%len(ThinkingStates)]
			thinkingMsg := Styles.Thinking.Render("FLOYD: " + state.Phrase)
			animation := GetAnimatedMicroInteraction(state.MicroInteraction, m.AnimationFrame)
			chatHistory.WriteString(thinkingMsg + " " + animation + "\n")
		}
	}

	// Add current streaming response
	if m.IsThinking && m.CurrentResponse.Len() > 0 {
		styled := Styles.FloydMsg.Render("FLOYD: " + m.CurrentResponse.String())
		chatHistory.WriteString(styled + "\n")
	}

	m.Viewport.SetContent(chatHistory.String())
	viewportContent := Styles.Viewport.Render(m.Viewport.View())

	// Multi-line input
	inputLines := strings.Split(m.Input.View(), "\n")
	inputPanelHeight := len(inputLines) + 2
	styledInput := Styles.Input.Height(inputPanelHeight).Render(m.Input.View())

	// Progress bar
	var progressBar string
	if m.ProgressActive {
		progressBar = m.Progress.View()
	}

	// Status bar
	statusText := m.buildStatusText()
	statusBar := Styles.StatusBar.Render(statusText)

	// Join everything
	mainContent := lipgloss.JoinVertical(lipgloss.Left,
		header,
		tagline,
		errorPanel,
		helpPanel,
		viewportContent,
		"", // spacer
		styledInput,
		progressBar,
		statusBar,
	)

	return Styles.Base.Render(mainContent)
}

// buildStatusText builds the status bar text
func (m Model) buildStatusText() string {
	status := "● READY"
	promptChar := "> "

	if m.ExecutingTools {
		status = fmt.Sprintf("● TOOLS: %s", m.CurrentToolName)
		promptChar = "▶ "
	} else if m.IsThinking {
		status = "● THINKING"
		promptChar = "█ "
	}

	themeInfo := fmt.Sprintf("Theme: %s", m.CurrentTheme.Name)
	msgCount := fmt.Sprintf("Messages: %d", len(m.Messages))

	// Build status line
	status = fmt.Sprintf("%s | %s | %s", status, msgCount, themeInfo)

	// Pad to fill width
	padding := m.Width - lipgloss.Width(status) - 10
	if padding < 0 {
		padding = 0
	}

	return status + strings.Repeat(" ", padding) + promptChar
}

// SimpleView returns a simplified view for CLI mode (no TUI)
func (m Model) SimpleView(input string) string {
	var sb strings.Builder

	sb.WriteString("\n")
	sb.WriteString(strings.Repeat("=", 60))
	sb.WriteString("\n")

	if input != "" {
		sb.WriteString(Styles.UserMsg.Render("YOU: " + input))
		sb.WriteString("\n")
	}

	for _, msg := range m.Messages {
		switch msg.Role {
		case "user":
			sb.WriteString(Styles.UserMsg.Render("YOU: " + msg.Content))
		case "assistant":
			sb.WriteString(Styles.FloydMsg.Render("FLOYD: " + msg.Content))
		case "system":
			if msg.ToolUse != nil {
				sb.WriteString(Styles.ToolUse.Render("▶ Tool: " + msg.ToolUse.Name))
			} else if msg.ToolResult != nil {
				prefix := "✓ "
				if msg.ToolResult.IsError {
					prefix = "✗ "
				}
				sb.WriteString(prefix + msg.ToolResult.Name)
			} else {
				sb.WriteString(Styles.SystemMsg.Render(msg.Content))
			}
		}
		sb.WriteString("\n")
	}

	sb.WriteString(strings.Repeat("=", 60))
	sb.WriteString("\n> ")

	return sb.String()
}

package floydui

import (
	"context"
	"fmt"
	"strings"
	"time"

	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/bubbles/progress"
	"github.com/charmbracelet/bubbles/viewport"
	"github.com/charmbracelet/lipgloss"

	"github.com/Nomadcxx/sysc-Go/agent"
	"github.com/Nomadcxx/sysc-Go/agent/loop"
)

// Update handles all message updates to the model
func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	var (
		cmd  tea.Cmd
		cmds []tea.Cmd
	)

	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.Width = msg.Width
		m.Height = msg.Height
		m.handleWindowSize()
		return m, tea.Batch(cmds...)

	case tea.KeyMsg:
		return m.handleKeyMsg(msg)

	case tickMsg:
		m.LastTick = time.Time(msg)
		m.AnimationFrame = (m.AnimationFrame + 1) % 20
		if m.IsThinking {
			if m.AnimationFrame%20 == 0 {
				m.CurrentThinking = (m.CurrentThinking + 1) % len(ThinkingStates)
			}
		}
		cmds = append(cmds, Tick(time.Millisecond*150))

	case thinkingStartedMsg:
		m.IsThinking = true
		m.AnimationFrame = 0
		m.CurrentThinking = 0
		m.ProgressActive = true
		m.ProgressPercent = 0.0

	case thinkingFinishedMsg:
		m.IsThinking = false
		m.ProgressActive = false
		m.AddAssistantMessage(msg.response)

	case streamTokenMsg:
		m.PendingTokens = append(m.PendingTokens, msg.token)
		m.CurrentResponse.WriteString(msg.token)
		if len(m.PendingTokens) >= 5 || time.Since(m.LastTick) > time.Millisecond*50 {
			m.flushTokens()
		}

	case streamErrorMsg:
		m.flushTokens()
		m.IsThinking = false
		m.ExecutingTools = false
		m.ProgressActive = false
		m.AddSystemMessage(fmt.Sprintf("Error: %v", msg.err))

	case toolUseMsg:
		m.AddToolUse(msg.toolName, msg.toolID)

	case toolExecutingMsg:
		m.ExecutingTools = true
		m.CurrentToolName = msg.toolName

	case toolResultMsg:
		m.ExecutingTools = false
		m.AddToolResult(msg.toolName, msg.content, false)

	case toolErrorMsg:
		m.ExecutingTools = false
		m.AddToolResult(msg.toolName, msg.content, true)

	case progressMsg:
		if m.ProgressActive {
			m.ProgressPercent = float64(msg)
			if m.ProgressPercent >= 1.0 {
				m.ProgressPercent = 1.0
			} else {
				cmds = append(cmds, func() tea.Msg {
					return progressMsg(m.ProgressPercent + 0.05)
				})
			}
		}

	case themeChangedMsg:
		// Theme already updated in SetTheme
		m.AddSystemMessage(fmt.Sprintf("Theme changed to '%s'.", m.CurrentTheme.Name))

	case subAgentSpawnMsg:
		m.AddSystemMessage(fmt.Sprintf("[SPAWN] %s agent: %s", msg.agentType, msg.task))

	case subAgentStatusMsg:
		m.AddSystemMessage(fmt.Sprintf("[SUB-AGENT] %s: %s", msg.status, msg.detail))

	case subAgentCompleteMsg:
		m.AddSystemMessage(fmt.Sprintf("[SUB-AGENT] Complete: %s", msg.result))
	}

	// Update child components
	m.Input, cmd = m.Input.Update(msg)
	cmds = append(cmds, cmd)

	m.Viewport, cmd = m.Viewport.Update(msg)
	cmds = append(cmds, cmd)

	if m.ProgressActive {
		var newModel tea.Model
		newModel, cmd = m.Progress.Update(m.ProgressPercent)
		m.Progress = newModel.(progress.Model)
		cmds = append(cmds, cmd)
	}

	return m, tea.Batch(cmds...)
}

// handleWindowSize handles window size changes
func (m *Model) handleWindowSize() {
	headerHeight := lipgloss.Height(Styles.Header.Render(PRISMBanner)) + lipgloss.Height(Styles.Tagline.Render(GetRandomTagline()))
	statusBarHeight := 1

	inputLines := strings.Count(m.Input.Value(), "\n") + 1
	inputHeight := inputLines + 2

	errorPanelHeight := 0
	if m.HasError {
		errorPanelHeight = lipgloss.Height(m.LastError) + 2
	}

	helpPanelHeight := 0
	if m.ShowHelp {
		helpPanelHeight = lipgloss.Height(HelpContent) + 2
	}

	verticalMargin := headerHeight + statusBarHeight + inputHeight + errorPanelHeight + helpPanelHeight

	if !m.Ready {
		m.Viewport = viewport.New(m.Width, m.Height-verticalMargin)
		m.Ready = true
	} else {
		m.Viewport.Width = m.Width - 4
		m.Viewport.Height = m.Height - verticalMargin
	}

	m.Input.Width = m.Width - 6
	m.Progress.Width = m.Width - 10
	m.updateViewportContent()
	m.Viewport.GotoBottom()
}

// handleKeyMsg handles keyboard input
func (m Model) handleKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	var cmds []tea.Cmd

	// Check for theme command
	if strings.HasPrefix(m.Input.Value(), "/theme ") {
		themeName := strings.TrimPrefix(m.Input.Value(), "/theme ")
		// Normalize theme name to lowercase
		themeName = strings.ToLower(themeName)
		if cmd := m.SetTheme(themeName); cmd != nil {
			m.Input.Reset()
			m.Viewport.GotoBottom()
			return m, cmd
		}
		// Error 7: Invalid theme error
		m.AddSystemMessage(fmt.Sprintf("Unknown theme '%s'. Available: classic, dark, highcontrast, cyberpunk, midnight", themeName))
		m.Input.Reset()
		m.updateViewportContent()
		m.Viewport.GotoBottom()
		return m, nil
	}

	switch msg.Type {
	case tea.KeyEnter:
		input := strings.TrimSpace(m.Input.Value())
		if input == "" {
			return m, nil
		}

		// Handle commands
		if strings.HasPrefix(input, "/") {
			// Error 10: Allow certain commands while thinking
			if m.IsThinking {
				cmdLower := strings.ToLower(input)
				if cmdLower == "/clear" || cmdLower == "/cls" || cmdLower == "/cancel" {
					// Cancel the current operation
					if m.StreamCancel != nil {
						m.StreamCancel()
					}
					m.ClearMessages()
					m.IsThinking = false
					m.ExecutingTools = false
					m.ProgressActive = false
					m.Input.Reset()
					m.AddSystemMessage("Operation cancelled.")
					m.updateViewportContent()
					m.Viewport.GotoBottom()
					return m, nil
				}
				// Other commands blocked while thinking
				m.AddSystemMessage("Cannot use commands while agent is working. Press Ctrl+C to quit.")
				m.Input.Reset()
				m.updateViewportContent()
				m.Viewport.GotoBottom()
				return m, nil
			}
			return m.handleCommand(input)
		}

		// Normal input blocked while thinking
		if m.IsThinking {
			return m, nil
		}

		// Add user message and start agent
		m.AddUserMessage(input)
		m.Input.Reset()
		m.CurrentResponse.Reset()
		m.IsThinking = true
		m.PendingTokens = m.PendingTokens[:0]

		cmds = append(cmds, m.startAgentCall(input))
		cmds = append(cmds, Tick(time.Millisecond*150))
		return m, tea.Batch(cmds...)

	case tea.KeyUp, tea.KeyShiftUp:
		if m.HistoryIndex > 0 {
			m.HistoryIndex--
			m.Input.SetValue(m.History[m.HistoryIndex])
		}
		// History navigation shouldn't update input through default handler
		return m, tea.Batch(cmds...)

	case tea.KeyDown, tea.KeyShiftDown:
		if m.HistoryIndex < len(m.History)-1 {
			m.HistoryIndex++
			m.Input.SetValue(m.History[m.HistoryIndex])
		} else if m.HistoryIndex == len(m.History)-1 {
			m.HistoryIndex++
			m.Input.Reset()
		}
		// History navigation shouldn't update input through default handler
		return m, tea.Batch(cmds...)

	case tea.KeyCtrlC, tea.KeyEsc:
		if m.StreamCancel != nil {
			m.StreamCancel()
		}
		// Save session before quitting
		_ = m.SaveCurrentSession()
		return m, tea.Quit

	case tea.KeyCtrlH:
		m.ShowHelp = !m.ShowHelp
		// Ctrl+H shouldn't update input through default handler
		return m, tea.Batch(cmds...)
	}

	// Handle ? key for help toggle (only when input is empty to avoid conflicts with typing)
	if msg.String() == "?" && m.Input.Value() == "" {
		m.ShowHelp = !m.ShowHelp
		return m, tea.Batch(cmds...)
	}

	// For all other keys, let the textinput component handle them
	// This includes character input (KeyRunes), backspace, space, etc.
	var cmd tea.Cmd
	m.Input, cmd = m.Input.Update(msg)
	cmds = append(cmds, cmd)

	return m, tea.Batch(cmds...)
}

// handleCommand handles slash commands
func (m Model) handleCommand(input string) (tea.Model, tea.Cmd) {
	cmd := strings.TrimPrefix(input, "/")
	parts := strings.Fields(cmd)
	if len(parts) == 0 {
		// Error 6: Empty command feedback
		m.AddSystemMessage("Usage: /command [args]. Type /help for available commands.")
		m.Input.Reset()
		m.updateViewportContent()
		m.Viewport.GotoBottom()
		return m, nil
	}

	switch strings.ToLower(parts[0]) {
	case "exit", "quit", "q":
		_ = m.SaveCurrentSession()
		return m, tea.Quit

	case "clear", "cls":
		m.ClearMessages()
		m.updateViewportContent()
		m.Viewport.GotoBottom()
		return m, nil

	case "help", "h":
		m.ShowHelp = !m.ShowHelp
		m.updateViewportContent()
		m.Viewport.GotoBottom()
		return m, nil

	case "status":
		status := m.ProtocolMgr.WorkspaceStatus()
		var sb strings.Builder
		sb.WriteString("📁 FLOYD Workspace Status:\n")
		for k, v := range status {
			sb.WriteString(fmt.Sprintf("  %s: %s\n", k, v))
		}
		m.AddSystemMessage(sb.String())
		m.updateViewportContent()
		m.Viewport.GotoBottom()
		return m, nil

	case "tools":
		// List available themes since /theme is the primary command
		themes := []string{"classic", "dark", "highcontrast", "cyberpunk", "midnight"}
		m.AddSystemMessage(fmt.Sprintf("Available themes: %s", strings.Join(themes, ", ")))
		m.Input.Reset()
		m.updateViewportContent()
		m.Viewport.GotoBottom()
		return m, nil

	case "protocol":
		masterPlan := m.ProtocolMgr.GetMasterPlan()
		stack := m.ProtocolMgr.GetStack()
		var sb strings.Builder
		sb.WriteString("📋 FLOYD Protocol Status:\n\n")
		if len(masterPlan) > 0 {
			sb.WriteString("Master Plan: Loaded\n")
		} else {
			sb.WriteString("Master Plan: Not found\n")
		}
		if len(stack) > 0 && !strings.Contains(stack, "not defined") {
			sb.WriteString("Tech Stack: Defined\n")
		} else {
			sb.WriteString("Tech Stack: Not defined\n")
		}
		m.AddSystemMessage(sb.String())
		m.updateViewportContent()
		m.Viewport.GotoBottom()
		return m, nil

	default:
		// Error 8: Unknown command feedback
		m.AddSystemMessage(fmt.Sprintf("Unknown command: /%s. Type /help for available commands.", parts[0]))
		m.Input.Reset()
		m.updateViewportContent()
		m.Viewport.GotoBottom()
		return m, nil
	}
}

// startAgentCall initiates a call to the agent
func (m *Model) startAgentCall(userInput string) tea.Cmd {
	return func() tea.Msg {
		ctx, cancel := context.WithCancel(context.Background())
		m.StreamCancel = cancel

		// Build request with protocol
		req := agent.ChatRequest{
			Messages:    m.Conversation,
			MaxTokens:   4096,
			Temperature: 0.7,
			Stream:      true,
		}

		// Inject protocol
		req = m.ProtocolMgr.EnhancedChatRequest(req, "")

		// Run the tool loop with streaming
		eventChan, err := m.LoopAgent.RunToolLoopStreaming(ctx, req)
		if err != nil {
			return streamErrorMsg{err: err}
		}

		// Process events in goroutine
		go func() {
			defer close(m.TokenStreamChan)

			for event := range eventChan {
				switch event.Type {
				case loop.EventTypeToken:
					select {
					case m.TokenStreamChan <- event.Text:
					case <-ctx.Done():
						return
					}

				case loop.EventTypeToolUse:
					select {
					case m.TokenStreamChan <- fmt.Sprintf("[Using tool: %s]", event.ToolName):
					case <-ctx.Done():
						return
					}

				case loop.EventTypeToolExecuting:
					// Show tool execution status
					select {
					case m.TokenStreamChan <- fmt.Sprintf("[Executing: %s]", event.ToolCall):
					case <-ctx.Done():
						return
					}

				case loop.EventTypeToolResult:
					// Show tool result (truncated if too long)
					resultContent := event.ToolContent
					if len(resultContent) > 300 {
						resultContent = resultContent[:300] + "..."
					}
					resultMsg := fmt.Sprintf("[Result: %s]", resultContent)
					if event.IsError {
						resultMsg = fmt.Sprintf("[Error: %s] %s", event.ToolName, resultContent)
					}
					select {
					case m.TokenStreamChan <- resultMsg:
					case <-ctx.Done():
						return
					}

				case loop.EventTypeDone:
					return

				case loop.EventTypeError:
					return
				}
			}
		}()

		return thinkingStartedMsg{}
	}
}

// flushTokens flushes pending tokens to viewport
func (m *Model) flushTokens() {
	if len(m.PendingTokens) == 0 {
		return
	}
	m.PendingTokens = m.PendingTokens[:0]
	m.LastTick = time.Now()
	m.updateViewportContent()
	m.Viewport.GotoBottom()
}

// updateViewportContent updates the viewport content
func (m *Model) updateViewportContent() {
	var chatHistory strings.Builder

	for _, msg := range m.Messages {
		var styled string
		switch msg.Role {
		case "user":
			styled = Styles.UserMsg.
				Width(m.Width-4).
				Render("YOU: " + msg.Content)
		case "assistant":
			if msg.IsStreaming {
				styled = Styles.FloydMsg.Render("FLOYD: " + m.CurrentResponse.String())
			} else {
				styled = Styles.FloydMsg.Render("FLOYD: " + msg.Content)
			}
		case "system":
			if msg.ToolUse != nil {
				styled = Styles.ToolUse.Render("▶ Using tool: " + msg.ToolUse.Name)
			} else if msg.ToolResult != nil {
				prefix := "✓ "
				if msg.ToolResult.IsError {
					prefix = "✗ "
				}
				content := msg.ToolResult.Content
				if len(content) > 200 {
					content = content[:200] + "..."
				}
				if msg.ToolResult.IsError {
					styled = Styles.ToolResultError.Render(prefix + msg.ToolResult.Name + ": " + content)
				} else {
					styled = Styles.ToolResult.Render(prefix + msg.ToolResult.Name + ": " + content)
				}
			} else {
				styled = Styles.SystemMsg.Render(msg.Content)
			}
		}
		chatHistory.WriteString(styled + "\n")
	}

	// Add current streaming response
	if m.IsThinking && m.CurrentResponse.Len() > 0 {
		styled := Styles.FloydMsg.Render("FLOYD: " + m.CurrentResponse.String())
		chatHistory.WriteString(styled + "\n")
	}

	m.Viewport.SetContent(chatHistory.String())
}

